"""Package both existing lectures and the extra bank into one portable folder."""
import json
from pathlib import Path
import shutil
import subprocess

ROOT=Path(__file__).resolve().parent
subprocess.run(['python3',str(ROOT/'make_catalog.py')],check=True)
css='''
:root{color-scheme:dark;--bg:#0b1018;--panel:#131d2b;--line:#29384c;--ink:#e8eff7;--muted:#9dacc0;--accent:#72edc5}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 system-ui,sans-serif}header{padding:30px max(22px,calc((100vw - 1440px)/2));border-bottom:1px solid var(--line);background:radial-gradient(ellipse at top right,#174d47,transparent 70%)}h1{font-size:clamp(30px,4vw,46px);line-height:1.15;margin:10px 0 18px}h2,h3{line-height:1.35}p{color:var(--muted)}a{color:var(--accent)}button,input,select,textarea{font:inherit}button,.button,select{background:#1c2b3e;border:1px solid #3e536c;color:var(--ink);border-radius:8px;padding:10px 14px;cursor:pointer;text-decoration:none;display:inline-block}button:hover,.button:hover,button.active{border-color:var(--accent);color:var(--accent)}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}nav{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.eyebrow{color:var(--accent);letter-spacing:3px;font-size:12px}.tag{display:inline-block;font-size:12px;border:1px solid #42796a;border-radius:30px;padding:4px 10px;color:var(--accent)}main{max-width:1480px;margin:auto;padding:24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:20px}.card,aside{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:22px}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.metric{font-size:40px;color:var(--accent)}.status{font-size:13px;color:var(--muted)}aside{position:sticky;top:16px;align-self:start;padding:16px}input[type=search]{width:100%;background:var(--bg);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:12px}select{max-width:100%;width:100%;margin-top:10px}#lab-list{max-height:54vh;overflow:auto;margin-top:12px}.ticket{display:block;width:100%;text-align:left;font-size:13px;padding:10px;margin:6px 0}.ticket span{display:block;font-size:11px;color:var(--accent);letter-spacing:1px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#080d14;padding:16px;border-radius:8px;font:14px/1.7 ui-monospace,monospace}.terminal{background:#070b11;border:1px solid #324458;border-radius:12px;overflow:hidden}.bar{background:#1b2939;padding:10px 16px;font:13px ui-monospace,monospace}.output{height:350px;overflow:auto;padding:18px;white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.7 ui-monospace,monospace}.terminal form{display:flex;gap:10px;align-items:center;padding:12px;border-top:1px solid var(--line)}.terminal input{flex:1;min-width:0;border:0;background:transparent;color:#c7f9dd;font:15px ui-monospace,monospace}.prompt{font:13px ui-monospace,monospace;color:var(--accent)}progress{width:100%;height:12px;accent-color:var(--accent)}.done{color:var(--accent)}details{border-top:1px solid var(--line);padding-top:12px;margin-top:14px}summary{cursor:pointer}textarea{width:100%;min-height:260px;resize:vertical;background:#080d14;color:var(--ink);border:1px solid var(--accent);border-radius:8px;padding:14px;font:14px/1.6 ui-monospace,monospace}#editor{border-color:var(--accent)}[hidden]{display:none!important}#mobile-picker{display:none}footer{max-width:1440px;margin:auto;padding:24px;color:var(--muted)}.import-label{font-size:13px;display:block;margin:12px 0}input[type=file]{max-width:100%;font-size:12px}.topics{columns:3;column-gap:30px}.topics li{break-inside:avoid}.guide{border-left:3px solid var(--accent);padding-left:18px}@media(max-width:850px){.layout{grid-template-columns:1fr}aside{position:static}#lab-list{display:none}#mobile-picker{display:block}#filters{display:grid;grid-template-columns:1fr 1fr;gap:10px}aside h2{margin:0 0 12px}main{padding:14px}.prompt{display:none}.topics{columns:2}}@media(max-width:450px){.topics{columns:1}.terminal form{flex-wrap:wrap}.output{height:310px}}'''
(ROOT/'shared.css').write_text(css)
def page(title,header,body,navprefix=''):
    nav=f'<nav aria-label="Course sections"><a class="button" href="{navprefix}index.html">Home</a><a class="button" href="{navprefix}lecture-02/index.html">Lecture 2</a><a class="button" href="{navprefix}lecture-03/index.html">Lecture 3</a><a class="button" href="{navprefix}other/index.html">Other · 120 labs</a></nav>'
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><link rel="stylesheet" href="'+navprefix+'shared.css"></head><body><header><div class="eyebrow">LINUX / LEARN · PRACTICE · VERIFY</div>'+header+nav+'</header><main>'+body+'</main><footer>Offline browser simulations · No real system access · Progress is saved per browser. Keep this folder together when copying it.</footer></body></html>'
home='''<div class="grid"><article class="card"><span class="tag">LECTURE 02</span><h2>Linux Administration Lab</h2><p>Users, groups, permissions, processes, services, networking, storage, scheduling and backup.</p><p class="metric">12 labs</p><a class="button" href="lecture-02/index.html">Open Lecture 2 →</a></article><article class="card"><span class="tag">LECTURE 03</span><h2>Server Engineering Lab</h2><p>Advanced Bash, security, SSH hardening, Nginx, monitoring, recovery and release engineering.</p><p class="metric">14 labs</p><a class="button" href="lecture-03/index.html">Open Lecture 3 →</a></article><article class="card"><span class="tag">OTHER</span><h2>Extra Practice Lab Bank</h2><p>120 additional tickets across 30 topics, with independent server state, search, filters, hints and verification.</p><p class="metric">120 labs</p><a class="button" href="other/index.html">Explore Other →</a></article></div><section class="card"><h2>One course workspace. 146 practice labs.</h2><p class="guide">Start with the lecture guides, practise their original tickets, then use Other for more scenarios. Every extra ticket has its own training server, checklist and solution. Editing, reset and command execution affect only that simulated server.</p><p>Use the navigation at the top of any section to switch between both lectures and Other. Original lecture pages keep their complete source lessons and existing local progress keys.</p><p>The entire folder works offline. External documentation links require internet. When moving between devices or browser profiles, use Other’s progress export and import; browser storage does not travel with copied files.</p></section>'''
(ROOT/'index.html').write_text(page('Linux Learning Labs — Lectures 2, 3 and Other','<h1>Linux Learning Labs</h1><p>Both lectures, one workspace, and a new bank of 120 hands-on practice tickets.</p>',home))
other='''<div class="layout"><aside><h2>Find a lab</h2><input id="search" type="search" aria-label="Search extra labs" placeholder="Search topic, ticket or scenario…"><div id="filters"><label class="status">Topic<select id="topic" aria-label="Topic filter"></select></label><label class="status">Progress<select id="scope" aria-label="Completion filter"><option value="all">All labs</option><option value="incomplete">To practise</option><option value="complete">Completed</option></select></label></div><p id="matching" class="status" role="status"></p><select id="mobile-picker" aria-label="Select a lab"></select><div id="lab-list" aria-label="Extra lab tickets"></div><p class="status" id="save-status"></p><details><summary>Export and transfer progress</summary><button id="export">Export transcript</button><button id="export-progress">Export progress</button><label class="import-label">Import progress JSON<input id="import-progress" type="file" accept="application/json,.json"></label><p id="import-status" class="status" role="status"></p></details></aside><div><section class="card"><div class="row"><span class="tag" id="lab-tag"></span><span id="result" class="status" role="status"></span></div><h2 id="lab-title"></h2><p id="scenario"></p><ol id="goals"></ol><progress id="progress" value="0" max="100" aria-label="Current lab completion"></progress><div class="row"><button id="check">Check work</button><button id="reset">Reset this lab</button><button id="next">Next lab →</button></div><details><summary>Hint and supported solution</summary><p id="hint"></p><pre id="solution"></pre></details></section><section id="editor" class="card" hidden><h3>Training file editor</h3><p id="editor-path"></p><textarea id="editor-text" aria-label="Virtual file content" spellcheck="false"></textarea><div class="row"><button id="save-file">Save file</button><button id="close-editor">Close</button><span id="editor-status" role="status"></span></div></section><section class="terminal"><div class="bar">● ● ● &nbsp; independent training server / simulated shell</div><div id="output" class="output" role="log" aria-live="polite" aria-label="Terminal output"></div><form id="shell"><span class="prompt">student@lab:~ $</span><input id="command" aria-label="Terminal command" placeholder="Type help for supported commands" autocomplete="off" autocapitalize="off" spellcheck="false"><button>Run ↵</button></form></section><p class="status">Enter runs a command · ↑ / ↓ browse history · Ctrl+L clears display · edit PATH opens the training editor. Unsupported syntax is reported. This simulator models the listed commands, not a full Linux system or Bash interpreter.</p></div></div><script src="labs.js"></script><script src="app.js"></script>'''
(ROOT/'other/index.html').write_text(page('Other — 120 Extra Linux Labs','<div class="row"><h1>Other · Extra Practice</h1><span class="tag" id="completed-count">0 / 120</span></div><p>120 different tickets across 30 topics from both lectures. Each ticket starts with independent state.</p>',other,'../'))
for number,source in [('02','admin-lab'),('03','server-lab')]:
    dest=ROOT/f'lecture-{number}'
    dest.mkdir(exist_ok=True)
    text=(ROOT.parent/source/'index.html').read_text()
    nav='<nav aria-label="Course navigation" style="padding:12px 20px;display:flex;gap:14px;flex-wrap:wrap;background:#131d2b;border-bottom:1px solid #29384c;font:14px system-ui"><a href="../index.html">← Learning Labs home</a><a href="../lecture-02/index.html">Lecture 2</a><a href="../lecture-03/index.html">Lecture 3</a><a href="../other/index.html">Other · 120 extra labs</a></nav>'
    text=text.replace('<header>',nav+'<header>',1)
    (dest/'index.html').write_text(text)
destination=Path('/home/haidary/Downloads/Linux_Learning_Labs')
destination.mkdir(exist_ok=True)
for name in ['index.html','shared.css','lecture-02','lecture-03','other']:
    src=ROOT/name
    if src.is_dir():shutil.copytree(src,destination/name,dirs_exist_ok=True)
    else:shutil.copy2(src,destination/name)
shutil.make_archive('/home/haidary/Downloads/Linux_Learning_Labs','zip',destination.parent,destination.name)
print(f'Packaged website: {destination}/index.html')
